1	// Package store owns the SQLite file and every write the service performs.
2	package store
3	
4	import (
5		"database/sql"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"slices"
10		"strings"
11		"time"
12	
13		_ "modernc.org/sqlite"
14	)
15	
16	// InitialStage is the stage every incident starts in when it is registered.
17	const InitialStage = "受理"
18	
19	// stageOrder lists the stages in the only order an incident may advance.
20	// Transitions move exactly one step forward along this list.
21	var stageOrder = []string{"受理", "遏制", "清除", "恢复", "关闭"}
22	
23	// nextStage returns the stage that immediately follows current, or false when
24	// current is the final stage (or otherwise has no successor).
25	func nextStage(current string) (string, bool) {
26		for i, stage := range stageOrder[:len(stageOrder)-1] {
27			if stage == current {
28				return stageOrder[i+1], true
29			}
30		}
31		return "", false
32	}
33	
34	// TimelineEntry records one stage of an incident's life together with the
35	// owner responsible at that point and the UTC time the entry was created.
36	type TimelineEntry struct {
37		Stage string `json:"stage"`
38		Owner string `json:"owner"`
39		At    string `json:"at"`
40	}
41	
42	// Incident is a registered ticket together with its full transition history.
43	type Incident struct {
44		ID       string          `json:"id"`
45		Severity string          `json:"severity"`
46		Assets   []string        `json:"assets"`
47		Stage    string          `json:"stage"`
48		Owner    string          `json:"owner"`
49		Timeline []TimelineEntry `json:"timeline"`
50	}
51	
52	// ErrIncidentConflict is returned when an id is registered again with
53	// different severity, assets, or owner.
54	var ErrIncidentConflict = errors.New("incident id already registered with different attributes")
55	
56	// ErrIncidentNotFound is returned when no incident exists for an id.
57	var ErrIncidentNotFound = errors.New("incident not found")
58	
59	// ErrInvalidTransition is returned when a transition does not advance the
60	// incident exactly one stage forward: requesting the current stage, going
61	// backward, skipping a stage, or moving on from the final stage.
62	var ErrInvalidTransition = errors.New("transition does not advance exactly one stage")
63	
64	// Store wraps the SQLite handle so callers never touch database/sql directly.
65	type Store struct {
66		db *sql.DB
67	}
68	
69	// Open prepares the database file and the schema this service needs.
70	func Open(path string) (*Store, error) {
71		db, err := sql.Open("sqlite", path)
72		if err != nil {
73			return nil, fmt.Errorf("open sqlite: %w", err)
74		}
75		// SQLite admits a single writer, so funnel every call through one
76		// connection: transactions then serialize instead of failing with
77		// SQLITE_BUSY, and a transaction never waits on a pool connection its
78		// own goroutine is holding.
79		db.SetMaxOpenConns(1)
80		if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
81			db.Close()
82			return nil, fmt.Errorf("enable wal: %w", err)
83		}
84		if _, err := db.Exec(schema); err != nil {
85			db.Close()
86			return nil, fmt.Errorf("apply schema: %w", err)
87		}
88		return &Store{db: db}, nil
89	}
90	
91	// Ping reports whether the storage layer is usable.
92	func (s *Store) Ping() error { return s.db.Ping() }
93	
94	// Close releases the database handle.
95	func (s *Store) Close() error { return s.db.Close() }
96	
97	// Register stores a new incident and its initial timeline entry in one
98	// transaction. Re-registering the same id with identical severity, assets
99	// (order included), and owner returns the stored record unchanged; any
100	// difference yields ErrIncidentConflict.
101	func (s *Store) Register(id, severity, owner string, assets []string) (Incident, error) {
102		existing, err := s.find(id)
103		if err != nil {
104			return Incident{}, err
105		}
106		if existing != nil {
107			return resolveDuplicate(existing, severity, owner, assets)
108		}
109	
110		encoded, err := json.Marshal(assets)
111		if err != nil {
112			return Incident{}, fmt.Errorf("encode assets: %w", err)
113		}
114		at := time.Now().UTC().Format(time.RFC3339)
115	
116		tx, err := s.db.Begin()
117		if err != nil {
118			return Incident{}, fmt.Errorf("begin register: %w", err)
119		}
120		if _, err = tx.Exec(
121			"INSERT INTO incidents (id, severity, assets, stage, owner) VALUES (?, ?, ?, ?, ?)",
122			id, severity, string(encoded), InitialStage, owner,
123		); err == nil {
124			if _, err = tx.Exec(
125				"INSERT INTO incident_timeline (incident_id, seq, stage, owner, at) VALUES (?, 0, ?, ?, ?)",
126				id, InitialStage, owner, at,
127			); err == nil {
128				err = tx.Commit()
129			}
130		}
131		if err != nil {
132			// Roll back before re-reading: the store runs on a single
133			// connection, which the open transaction is still holding.
134			tx.Rollback()
135			// A concurrent register of the same id may have won the race.
136			if existing, findErr := s.find(id); findErr == nil && existing != nil {
137				return resolveDuplicate(existing, severity, owner, assets)
138			}
139			return Incident{}, fmt.Errorf("register incident: %w", err)
140		}
141	
142		return Incident{
143			ID:       id,
144			Severity: severity,
145			Assets:   assets,
146			Stage:    InitialStage,
147			Owner:    owner,
148			Timeline: []TimelineEntry{{Stage: InitialStage, Owner: owner, At: at}},
149		}, nil
150	}
151	
152	// Transition advances the incident registered under id to stage, which must
153	// be the immediate successor of the current stage, and appends a timeline
154	// entry with owner and a service-generated UTC timestamp. The stage, owner,
155	// and history entry commit in one transaction: either all are stored or none
156	// is. A concurrent transition of the same incident loses the race and
157	// returns ErrInvalidTransition; a missing id returns ErrIncidentNotFound.
158	func (s *Store) Transition(id, stage, owner string) (Incident, error) {
159		tx, err := s.db.Begin()
160		if err != nil {
161			return Incident{}, fmt.Errorf("begin transition: %w", err)
162		}
163		defer tx.Rollback()
164	
165		incident, err := scanIncident(tx.QueryRow(
166			"SELECT id, severity, assets, stage, owner FROM incidents WHERE id = ?", id))
167		if errors.Is(err, sql.ErrNoRows) {
168			return Incident{}, ErrIncidentNotFound
169		}
170		if err != nil {
171			return Incident{}, fmt.Errorf("load incident: %w", err)
172		}
173	
174		next, ok := nextStage(incident.Stage)
175		if !ok || next != stage {
176			return Incident{}, ErrInvalidTransition
177		}
178	
179		at := time.Now().UTC().Format(time.RFC3339)
180		result, err := tx.Exec(
181			"UPDATE incidents SET stage = ?, owner = ? WHERE id = ? AND stage = ?",
182			stage, owner, id, incident.Stage)
183		if err != nil {
184			return Incident{}, fmt.Errorf("update stage: %w", err)
185		}
186		if affected, err := result.RowsAffected(); err != nil || affected != 1 {
187			// Another transition moved the incident between our read and write.
188			return Incident{}, ErrInvalidTransition
189		}
190	
191		var seq int
192		if err := tx.QueryRow(
193			"SELECT COALESCE(MAX(seq), -1) + 1 FROM incident_timeline WHERE incident_id = ?", id,
194		).Scan(&seq); err != nil {
195			return Incident{}, fmt.Errorf("read timeline seq: %w", err)
196		}
197		if _, err := tx.Exec(
198			"INSERT INTO incident_timeline (incident_id, seq, stage, owner, at) VALUES (?, ?, ?, ?, ?)",
199			id, seq, stage, owner, at,
200		); err != nil {
201			return Incident{}, fmt.Errorf("append timeline: %w", err)
202		}
203	
204		timeline, err := queryTimeline(tx, id)
205		if err != nil {
206			return Incident{}, err
207		}
208		if err := tx.Commit(); err != nil {
209			return Incident{}, fmt.Errorf("commit transition: %w", err)
210		}
211	
212		incident.Stage = stage
213		incident.Owner = owner
214		incident.Timeline = timeline
215		return incident, nil
216	}
217	
218	// Get returns the incident registered under id, or ErrIncidentNotFound.
219	func (s *Store) Get(id string) (Incident, error) {
220		incident, err := s.find(id)
221		if err != nil {
222			return Incident{}, err
223		}
224		if incident == nil {
225			return Incident{}, ErrIncidentNotFound
226		}
227		return *incident, nil
228	}
229	
230	// List returns every incident matching the optional severity and stage
231	// filters, ordered by id in UTF-8 byte order. Empty filters match everything.
232	func (s *Store) List(severity, stage string) ([]Incident, error) {
233		query := "SELECT id, severity, assets, stage, owner FROM incidents"
234		var clauses []string
235		var args []any
236		if severity != "" {
237			clauses = append(clauses, "severity = ?")
238			args = append(args, severity)
239		}
240		if stage != "" {
241			clauses = append(clauses, "stage = ?")
242			args = append(args, stage)
243		}
244		if len(clauses) > 0 {
245			query += " WHERE " + strings.Join(clauses, " AND ")
246		}
247		query += " ORDER BY id"
248	
249		rows, err := s.db.Query(query, args...)
250		if err != nil {
251			return nil, fmt.Errorf("list incidents: %w", err)
252		}
253		incidents := []Incident{}
254		for rows.Next() {
255			incident, err := scanIncident(rows)
256			if err != nil {
257				rows.Close()
258				return nil, err
259			}
260			incidents = append(incidents, incident)
261		}
262		if err := rows.Err(); err != nil {
263			rows.Close()
264			return nil, fmt.Errorf("list incidents: %w", err)
265		}
266		rows.Close()
267	
268		for i := range incidents {
269			timeline, err := s.timeline(incidents[i].ID)
270			if err != nil {
271				return nil, err
272			}
273			incidents[i].Timeline = timeline
274		}
275		return incidents, nil
276	}
277	
278	// find loads one incident by id, returning nil when it does not exist.
279	func (s *Store) find(id string) (*Incident, error) {
280		row := s.db.QueryRow(
281			"SELECT id, severity, assets, stage, owner FROM incidents WHERE id = ?", id)
282		incident, err := scanIncident(row)
283		if errors.Is(err, sql.ErrNoRows) {
284			return nil, nil
285		}
286		if err != nil {
287			return nil, err
288		}
289		timeline, err := s.timeline(id)
290		if err != nil {
291			return nil, err
292		}
293		incident.Timeline = timeline
294		return &incident, nil
295	}
296	
297	// timeline loads the transition history of one incident in entry order.
298	func (s *Store) timeline(id string) ([]TimelineEntry, error) {
299		return queryTimeline(s.db, id)
300	}
301	
302	// queryTimeline is timeline against any handle, so a transaction can read
303	// history through its own connection instead of waiting on the pool.
304	func queryTimeline(q interface {
305		Query(query string, args ...any) (*sql.Rows, error)
306	}, id string) ([]TimelineEntry, error) {
307		rows, err := q.Query(
308			"SELECT stage, owner, at FROM incident_timeline WHERE incident_id = ? ORDER BY seq", id)
309		if err != nil {
310			return nil, fmt.Errorf("read timeline: %w", err)
311		}
312		defer rows.Close()
313	
314		entries := []TimelineEntry{}
315		for rows.Next() {
316			var entry TimelineEntry
317			if err := rows.Scan(&entry.Stage, &entry.Owner, &entry.At); err != nil {
318				return nil, fmt.Errorf("read timeline: %w", err)
319			}
320			entries = append(entries, entry)
321		}
322		if err := rows.Err(); err != nil {
323			return nil, fmt.Errorf("read timeline: %w", err)
324		}
325		return entries, nil
326	}
327	
328	// resolveDuplicate decides whether a repeated registration is the same
329	// incident (returned unchanged) or a conflicting one.
330	func resolveDuplicate(existing *Incident, severity, owner string, assets []string) (Incident, error) {
331		if existing.Severity == severity && existing.Owner == owner && slices.Equal(existing.Assets, assets) {
332			return *existing, nil
333		}
334		return Incident{}, ErrIncidentConflict
335	}
336	
337	// scanner is the common shape of QueryRow/Query results over the incidents table.
338	type scanner interface {
339		Scan(dest ...any) error
340	}
341	
342	func scanIncident(row scanner) (Incident, error) {
343		var incident Incident
344		var encoded string
345		if err := row.Scan(&incident.ID, &incident.Severity, &encoded, &incident.Stage, &incident.Owner); err != nil {
346			return Incident{}, err
347		}
348		if err := json.Unmarshal([]byte(encoded), &incident.Assets); err != nil {
349			return Incident{}, fmt.Errorf("decode assets: %w", err)
350		}
351		return incident, nil
352	}
353	
354	const schema = `
355	CREATE TABLE IF NOT EXISTS service_metadata (
356		key   TEXT PRIMARY KEY,
357		value TEXT NOT NULL
358	);
359	CREATE TABLE IF NOT EXISTS incidents (
360		id       TEXT PRIMARY KEY,
361		severity TEXT NOT NULL,
362		assets   TEXT NOT NULL,
363		stage    TEXT NOT NULL,
364		owner    TEXT NOT NULL
365	);
366	CREATE TABLE IF NOT EXISTS incident_timeline (
367		incident_id TEXT NOT NULL REFERENCES incidents(id),
368		seq         INTEGER NOT NULL,
369		stage       TEXT NOT NULL,
370		owner       TEXT NOT NULL,
371		at          TEXT NOT NULL,
372		PRIMARY KEY (incident_id, seq)
373	);
374	`
