	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	timeline, err := s.timeline(id)
	if err != nil {
		return nil, err
	}
	incident.Timeline = timeline
	return &incident, nil
}

